:root {
  --color-bg: #ffffff;
  --color-text: #1a1a1a;
  --color-primary: #0056b3;
  --color-primary-hover: #003d82;
  --color-secondary: #6c757d;
  --color-border: #dee2e6;
  --color-focus: #0056b3;
  --color-error-bg: #f8d7da;
  --color-error-text: #721c24;
  --color-success-bg: #d4edda;
  --color-success-text: #155724;
  --font-sans: system-ui, -apple-system, sans-serif;
  --font-mono: ui-monospace, monospace;
  --spacing-unit: 1rem;
  --max-width: 1200px;
}

@media (prefers-color-scheme: dark) {
  :root {
    --color-bg: #121212;
    --color-text: #e0e0e0;
    --color-primary: #4dabf7;
    --color-primary-hover: #74c0fc;
    --color-secondary: #adb5bd;
    --color-border: #333333;
    --color-focus: #4dabf7;
    --color-error-bg: #3d1f24;
    --color-error-text: #f5c6cb;
    --color-success-bg: #1e3d2a;
    --color-success-text: #c3e6cb;
  }
}

* {
  box-sizing: border-box;
}

html {
  font-size: 100%;
  scroll-behavior: smooth;
}

body {
  margin: 0;
  font-family: var(--font-sans);
  line-height: 1.6;
  color: var(--color-text);
  background-color: var(--color-bg);
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

/* Skip Link */
.skip-link {
  position: absolute;
  top: -40px;
  left: 0;
  background: var(--color-primary);
  color: white;
  padding: 8px 16px;
  z-index: 100;
  transition: top 0.3s;
  text-decoration: none;
  font-weight: bold;
}

.skip-link:focus {
  top: 0;
}

/* Focus Indicators */
:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 2px;
}

/* Layout */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--spacing-unit);
  width: 100%;
}

/* Header & Nav */
.site-header {
  border-bottom: 1px solid var(--color-border);
  padding: var(--spacing-unit) 0;
  background-color: var(--color-bg);
}

.nav-wrapper {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.nav-toggle {
  display: none;
  background: none;
  border: 1px solid var(--color-border);
  font-size: 1.5rem;
  cursor: pointer;
  padding: 0.25rem 0.5rem;
  border-radius: 4px;
}

.primary-nav ul {
  display: flex;
  gap: var(--spacing-unit);
  list-style: none;
  margin: 0;
  padding: 0;
}

.primary-nav a {
  text-decoration: none;
  color: var(--color-text);
  font-weight: 500;
  padding: 0.25rem 0.5rem;
  border-radius: 4px;
}

.primary-nav a:hover,
.primary-nav a[aria-current="page"] {
  color: var(--color-primary);
  background-color: rgba(0, 86, 179, 0.1);
}

@media (max-width: 768px) {
  .nav-toggle {
    display: block;
  }

  .primary-nav {
    display: none;
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background: var(--color-bg);
    border-bottom: 1px solid var(--color-border);
    padding: var(--spacing-unit);
    box-shadow: 0 4px 6px rgba(0,0,0,0.1);
  }

  .primary-nav.is-open {
    display: block;
  }

  .primary-nav ul {
    flex-direction: column;
    gap: 0.5rem;
  }
}

/* Main Content */
main {
  padding: var(--spacing-unit) 0;
  flex: 1;
}

/* Footer */
.site-footer {
  border-top: 1px solid var(--color-border);
  padding: var(--spacing-unit) 0;
  margin-top: auto;
  background-color: var(--color-bg);
}

/* Components */
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--spacing-unit);
}

.project-card, .blog-card, .tool-card {
  border: 1px solid var(--color-border);
  padding: var(--spacing-unit);
  border-radius: 4px;
  background-color: var(--color-bg);
  transition: box-shadow 0.2s;
}

.project-card:hover, .blog-card:hover, .tool-card:hover {
  box-shadow: 0 2px 8px rgba(0,0,0,0.1);
}

.project-card h3, .blog-card h3, .tool-card h3 {
  margin-top: 0;
}

.filter-buttons {
  display: flex;
  gap: 0.5rem;
  margin-bottom: var(--spacing-unit);
  flex-wrap: wrap;
}

.filter-btn {
  padding: 0.5rem 1rem;
  border: 1px solid var(--color-border);
  background: var(--color-bg);
  cursor: pointer;
  border-radius: 4px;
  font-family: inherit;
}

.filter-btn[aria-pressed="true"] {
  background: var(--color-primary);
  color: white;
  border-color: var(--color-primary);
}

/* Forms */
.contact-form {
  max-width: 600px;
}

.form-group {
  margin-bottom: var(--spacing-unit);
}

label {
  display: block;
  margin-bottom: 0.25rem;
  font-weight: 500;
}

input, textarea, select {
  width: 100%;
  padding: 0.5rem;
  border: 1px solid var(--color-border);
  border-radius: 4px;
  font-family: inherit;
  font-size: 1rem;
}

input:focus, textarea:focus, select:focus {
  border-color: var(--color-primary);
}

.error-summary {
  background: var(--color-error-bg);
  color: var(--color-error-text);
  padding: 1rem;
  border-radius: 4px;
  margin-bottom: var(--spacing-unit);
  border: 1px solid var(--color-error-text);
}

.error-summary h2 {
  margin-top: 0;
  font-size: 1.25rem;
}

.success-message {
  background: var(--color-success-bg);
  color: var(--color-success-text);
  padding: 1rem;
  border-radius: 4px;
  margin-bottom: var(--spacing-unit);
  border: 1px solid var(--color-success-text);
}

/* Utilities */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

.back-to-top {
  position: fixed;
  bottom: 20px;
  right: 20px;
  background: var(--color-primary);
  color: white;
  border: none;
  padding: 0.75rem;
  border-radius: 50%;
  cursor: pointer;
  opacity: 0;
  transition: opacity 0.3s;
  z-index: 50;
}

.back-to-top:hover {
  background: var(--color-primary-hover);
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  .skip-link {
    transition: none;
  }

  .back-to-top {
    transition: none;
  }
}
